   288→PyObject* JSONFileToObj(PyObject* self, PyObject *args, PyObject *kwargs)
   289→{
   290→  PyObject *read;
   291→  PyObject *string;
   292→  PyObject *result;
   293→  PyObject *file = NULL;
   294→  PyObject *argtuple;
   295→
   296→  if (!PyArg_ParseTuple (args, "O", &file))
   297→  {
   298→    return NULL;
   299→  }
   300→
   301→  if (!PyObject_HasAttrString (file, "read"))
   302→  {
   303→    PyErr_Format (PyExc_TypeError, "expected file");
   304→    return NULL;
   305→  }
   306→
   307→  read = PyObject_GetAttrString (file, "read");
   308→
   309→  if (!PyCallable_Check (read)) {
   310→    Py_XDECREF(read);
   311→    PyErr_Format (PyExc_TypeError, "expected file");
   312→    return NULL;
   313→  }
   314→
   315→  string = PyObject_CallObject (read, NULL);
   316→  Py_XDECREF(read);
   317→
   318→  if (string == NULL)
   319→  {
   320→    return NULL;
   321→  }
   322→
   323→  argtuple = PyTuple_Pack(1, string);
   324→
   325→  result = JSONToObj (self, argtuple, kwargs);
   326→
   327→  Py_XDECREF(argtuple);
   328→  Py_XDECREF(string);
   329→
   330→  if (result == NULL) {
   331→    return NULL;
   332→  }
   333→
   334→  return result;
   335→}
